-- 20261006240000_m820_guideline_criteria.sql · DWA-M 820-1 / -2 / -3 — gate severity by the printed modal verb + settled encoding notes
-- Owner rule (2026-10-06, verbatim): "here are the real guidelines we should stick to them … just follow them with the correct criteria for our tool."
-- Criterion: severity follows the modal verb printed in the clause the gate encodes — „muss / ist … zu / erforderlich / darf nicht / zwingend“ → block;
-- „soll / sollte“ → warn; „kann / empfohlen / bewährt hat sich / hilfreich“ → info, kept as WARN (the engine evaluates info nowhere: approval-gate.ts
-- selects severity = 'block' only and compliance-block.tsx renders every non-warn failure as a red block ✗ — an 'info' row would LOOK like a block).
-- A gate whose check has no printed clause (scope checks, sum == total, dual sign-off, "phase not reached yet") is a TOOL gate → warn, and its hint says so.
-- A printed clause WITHOUT a listed modal verb (indicative target state, "Zielsetzung") or with two modals for the encoded content is NOT decided here:
-- severity stays as it is and the gate is listed for the owner (vault 48_SIGN-OFF-m820-guideline-criteria.md).
-- Audit table (all 137 gates, quote ≤ 15 words + PDF page, re-rendered 2026-10-06 with scoop pdftotext -layout from
--   C:\Users\Ekowai\Desktop\Guidelines\DWA-M-820-{1,2,3}\DWA-M_820-{1,2,3}.pdf; printed page = PDF page − 2):
--   vault 01-Projects/ekowai-wizard/m820-wizard-test/46_GATE-SEVERITY-AUDIT-m820_2026-10-06.md · apply order 47_ · sign-off 48_.
--
-- WHAT CHANGES (plain English):
--   Severity block → warn (7): 820-1 REQ-01, 820-1 REQ-15, 820-1 REQ-19, 820-1 REQ-25, 820-2 REQ-01, 820-3 REQ-01, 820-3 REQ-32
--   Severity warn → block (10): 820-1 REQ-14, 820-2 REQ-26, 820-2 REQ-15, 820-2 REQ-35, 820-2 REQ-42, 820-2 REQ-45, 820-2 REQ-50, 820-2 REQ-59, 820-3 REQ-05, 820-3 REQ-31
--     (820-3 REQ-31 only once block 20261006230000 "Projektstopp code per path" is applied — guarded on M8203-24-D1 md5 0e7c0e64ba6c08ac022ea68a58e71ed3; otherwise it stays warn
--      because the code never computes for a single-path project and a block gate that waits refuses approval.)
--   VgV-F guard (44_ 1-6 / 1-7, REQ-10's form): 820-1 REQ-19 / REQ-20 / REQ-21 / REQ-23; their guard symbols reach the four sheets (consumer lists).
--   clause_reference fixes: 820-1 REQ-02 → "§4.1, §6.2"; 820-1 REQ-11 → "§8.7, Anh. E.1.2"; 820-1 REQ-14 → "§8.10.3.3, Anh. E.2"; 820-2 REQ-53 → "§6.3.1, §6.3.2"; 820-2 REQ-35 → "§5.4.1, §5.4.3"; 820-2 REQ-54 → "§6.3.1, §6.3.3"; 820-2 REQ-56 → "§7.2, §7.6.2"; 820-2 REQ-57 → "§8.2.1"
--   Tool gates whose hint did not say so get one sentence ("Werkzeug-Prüfung … warnt nur").
--   44_ 1-3: client type "vergleichbare_institution" + ANHB23 row 139.000 € · 1-4: REQ-24 already reads "unter" (hint wave; nothing to change)
--   44_ 2-1: applicable_din/dwa_standards § 6.2 → § 6.1 · 2-5: change_log_present label + hint (LOP ≠ change register)
--   44_ 2-6: projektsteuerung_scope + "keine" (tool option) · mgmt_cycle_frequency + "monatlich" (printed in § 5.6.1, PDF S. 53)
--   44_ 3-1: every QE register (12) accepts project-specific rows: catalogue row "E" in the 10 QE tables + text column "Ergänzung (Kriterium)" (required on
--            E rows only); D1–D9 of the 8 unsplit registers skip E rows (nr != 'E'), the 4 split registers already skip them (in_teil = 0 via nr_num 0)
--   44_ 3-2: the 12 *_items_rated labels/hints say what D5 counts · 3-3: pz_64_12_status, pz_66_11_status required like their siblings
--   44_ 3-5: four optional goal fields (§ 7.2.2 × 2 on M8203-19, § 7.5.2 × 2 on M8203-21), boolean, BIM-only like their siblings, read by no gate
--
-- Guards: every UPDATE matches the LIVE pre-state (md5 of condition + description, severity, clause / the live jsonb, arrays, labels; md5 of formula);
-- inserts are NOT EXISTS + ledger. Idempotent (a re-run changes nothing). In-transaction archives (compliance_requirements_archive_m820_gc, fields_archive_m820_gc, equations_archive_m820_gc) + ledgers
-- (m820_gc_written: md5 of every row as written; m820_gc_added: inserted rows). Rollback: scripts/rollback-20261006240000-m820-guideline-criteria.sql (byte-equal; a row
-- edited after the apply is left alone). Read-back: scripts/verification/apply/readback-20261006240000-m820-guideline-criteria.sql. Nothing is (de)activated.
-- Order: AFTER the hint blocks 20261006220000 / 221000 / 222000 (they rewrite the same descriptions unconditionally); before or after 20261006230000.
-- STAGED — not applied.
BEGIN;

CREATE TABLE IF NOT EXISTS compliance_requirements_archive_m820_gc AS SELECT * FROM compliance_requirements WHERE false;
CREATE TABLE IF NOT EXISTS fields_archive_m820_gc AS SELECT * FROM fields WHERE false;
CREATE TABLE IF NOT EXISTS equations_archive_m820_gc AS SELECT * FROM equations WHERE false;
CREATE TABLE IF NOT EXISTS m820_gc_written (tbl text NOT NULL, id uuid NOT NULL, md5 text NOT NULL, PRIMARY KEY (tbl, id));
CREATE TABLE IF NOT EXISTS m820_gc_added (tbl text NOT NULL, id uuid NOT NULL, md5 text NOT NULL, PRIMARY KEY (tbl, id));

-- ── 1. gates ──
-- DWA-M-820-1 M820-01 REQ-01: severity, description (block → warn; tool; „— (Werkzeug-Prüfung)“)
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND cr.code = 'REQ-01'
   AND md5(cr.condition) = '7a91d3b4e2a3630009186351f825de08' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = 'ba01cf187a4182d016bf5458182eda96'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$§1$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET severity = $m$warn$m$,
       description = $m$Werkzeug-Prüfung (Geltungsbereich, keine gedruckte Pflicht) – warnt nur, sperrt die Freigabe nicht. Prüft, ob ein Sektor gewählt ist. §1 (S. 10): Die Empfehlungen beziehen sich „im Wesentlichen auf Ingenieurleistungen für Projekte im Bereich Wasserwirtschaft, Wasserbau, Abwasser und Abfall“. Jede Auswahl der Liste (auch „Sonstige“) besteht; bei „Sonstige“ die Zuordnung zum Anwendungsbereich selbst begründen. Dazu den Sektor auf diesem Blatt eintragen.
[EN] Tool check (scope, not a printed duty) – warns only, never blocks approval. Checks that a sector is chosen. §1 (p. 10): the recommendations relate "essentially to engineering services for projects in Wasserwirtschaft, Wasserbau, Abwasser and Abfall". Every list option (including "Other") passes; for "Other", justify the scope fit yourself. Enter the sector on this sheet.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-01' AND cr.code = 'REQ-01'
   AND md5(cr.condition) = '7a91d3b4e2a3630009186351f825de08' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = 'ba01cf187a4182d016bf5458182eda96'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$§1$m$;
-- DWA-M-820-1 M820-03 REQ-04: description
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND cr.code = 'REQ-04'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e' AND cr.severity = 'warn' AND md5(coalesce(cr.description, '')) = '911c3047a40f25407940b88f01676171'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$5$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET description = $m$Soll bestätigen, dass alle fünf Beteiligten-Kategorien aus §5 erfasst sind: Auftraggeber, Auftragnehmer, ausführende Firmen, Behörden, Öffentlichkeit. §5.1 (S. 23): „Bei jeder Planung gibt es einen Auftraggeber und oftmals mehrere Auftragnehmer.“ Dazu die Beteiligten-Liste auf diesem Blatt vollständig pflegen. Werkzeug-Prüfung (keine gedruckte Vorgabe des Merkblatts) – warnt nur, sperrt die Freigabe nicht.
[EN] Confirms all five §5 stakeholder categories are captured: client, contractor, executing firms, authorities, public. §5.1 (p. 23): "Every planning has a client and often several contractors." Keep the stakeholder list on this sheet complete to satisfy it. Tool check (not a printed requirement of the Merkblatt) – warns only, never blocks approval.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-03' AND cr.code = 'REQ-04'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e' AND cr.severity = 'warn' AND md5(coalesce(cr.description, '')) = '911c3047a40f25407940b88f01676171'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$5$m$;
-- DWA-M-820-1 M820-04 REQ-02: clause_reference
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-04' AND cr.code = 'REQ-02'
   AND md5(cr.condition) = 'fec31659c012fa3aee0f1064c46f58fe' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = '76f08a69051b98853d554a4832d617c1'
