   AND md5(cr.condition) = 'fec31659c012fa3aee0f1064c46f58fe' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = '76f08a69051b98853d554a4832d617c1'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$§6.2$m$;
-- DWA-M-820-1 M820-10 REQ-11: clause_reference
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND cr.code = 'REQ-11'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e' AND cr.severity = 'warn' AND md5(coalesce(cr.description, '')) = '96789606b7b651059970a8befb694d50'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$E.1.2$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET clause_reference = $m$§8.7, Anh. E.1.2$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-10' AND cr.code = 'REQ-11'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e' AND cr.severity = 'warn' AND md5(coalesce(cr.description, '')) = '96789606b7b651059970a8befb694d50'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$E.1.2$m$;
-- DWA-M-820-1 M820-14 REQ-14: severity, description, clause_reference (warn → block; source; „ist verpflichtet … anzugeben“)
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND cr.code = 'REQ-14'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e' AND cr.severity = 'warn' AND md5(coalesce(cr.description, '')) = '67bd1627a79809127fa92247c52f2a9c'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$E.2$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET severity = $m$block$m$,
       description = $m$Bestätigung durch den Ingenieur (die Prüfung hat keine auswertbare Bedingung), Schwere Blockade nach dem gedruckten „ist verpflichtet“: §8.10.3.3 (S. 40): „Der Auftraggeber ist verpflichtet, spätestens bei der Aufforderung zur Angebotsabgabe, besser bereits bei der Bekanntmachung, die Zuschlagskriterien und deren Gewichtung anzugeben (§ 127 GWB).“ Zuschlagskriterien nach Anhang E.2 festlegen (Schlüsselpersonal, Bauüberwachung, Organisation usw.).
[EN] Engineer confirmation (the check has no evaluable condition), severity block after the printed "ist verpflichtet" (is obliged): §8.10.3.3 (p. 40): "the client is obliged to state the award criteria and their weighting at the latest when inviting tenders, better already in the publication notice (§ 127 GWB)." Fix the award criteria per Anhang E.2 (key personnel, site supervision, organisation etc.).$m$,
       clause_reference = $m$§8.10.3.3, Anh. E.2$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND cr.code = 'REQ-14'
   AND md5(cr.condition) = 'd41d8cd98f00b204e9800998ecf8427e' AND cr.severity = 'warn' AND md5(coalesce(cr.description, '')) = '67bd1627a79809127fa92247c52f2a9c'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$E.2$m$;
-- DWA-M-820-1 M820-14 REQ-15: severity, description (block → warn; source; „bewährt hat sich“)
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND cr.code = 'REQ-15'
   AND md5(cr.condition) = 'bb8bdc5d4a88cfe09143542ada518a6e' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = '537963ccbef29fc4f1d300b14f123ae5'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$Anh. E.2.8$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET severity = $m$warn$m$,
       description = $m$Warnt (sperrt die Freigabe nicht), wenn die Preisgewichtung über 20 % liegt und kein Festpreis verwendet wird (dann 0 %). Anh. E.2.8 (S. 64) druckt eine Erfahrung, keine Pflicht: „Bewährt hat sich ein Bewertungsgewicht für den Preis in Höhe von max. 20 %.“ Eine höhere Preisgewichtung im Vergabevermerk begründen.
[EN] Warns (does not block approval) when the price weighting exceeds 20% and no Festpreis is used (then 0%). Anh. E.2.8 (p. 64) prints experience, not a duty: "a price weighting of max. 20% has proven effective." Justify a higher price weighting in the procurement memo.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-14' AND cr.code = 'REQ-15'
   AND md5(cr.condition) = 'bb8bdc5d4a88cfe09143542ada518a6e' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = '537963ccbef29fc4f1d300b14f123ae5'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$Anh. E.2.8$m$;
-- DWA-M-820-1 M820-18 REQ-19: severity, condition, description (block → warn; tool; „— (Werkzeug-Prüfung)“)
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND cr.code = 'REQ-19'
   AND md5(cr.condition) = '5ba06773511c88dec26fb0b422312c6d' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = 'bd0208c2d088d68e04dec5bdfc16382c'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$§8.10.2.4$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET severity = $m$warn$m$,
       condition = $m$IF (client_organization_type != 'privat_ohne_foerderung' OR vergaberecht_freiwillig_angewendet == true) AND procurement_procedure == 'vgv_f' THEN (applicant_count >= shortlisted_count)$m$,
       description = $m$Werkzeug-Prüfung (Plausibilität, keine gedruckte Vorgabe) – warnt nur, sperrt die Freigabe nicht. Gilt beim VgV-F-Verfahren (procurement_procedure auf M820-10), wenn der Auftraggeber an das Vergaberecht gebunden ist (kein privater Auftraggeber ohne Fördermittel, oder vergaberecht_freiwillig_angewendet = ja; beides auf M820-01). Bei Suchverfahren, Direktvergabe oder Planungswettbewerb prüft sie nicht. Dann soll applicant_count mindestens shortlisted_count sein (dieses Blatt). §8.10.2.4 (S. 39): „Nur nach diesen Kriterien darf die Wertung der Bewerbungen erfolgen.“
[EN] Tool check (plausibility, not a printed requirement) – warns only, never blocks approval. Applies in a VgV-F procedure (procurement_procedure on M820-10) when the client is bound by procurement law (not a private client without public funding, or vergaberecht_freiwillig_angewendet = yes; both on M820-01). It does not check in a search procedure, direct award or design competition. Then applicant_count should be at least shortlisted_count (this sheet). §8.10.2.4 (p. 39): "the applications may be scored only by these criteria."$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-18' AND cr.code = 'REQ-19'
   AND md5(cr.condition) = '5ba06773511c88dec26fb0b422312c6d' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = 'bd0208c2d088d68e04dec5bdfc16382c'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$§8.10.2.4$m$;
-- DWA-M-820-1 M820-20 REQ-20: condition, description
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND cr.code = 'REQ-20'
   AND md5(cr.condition) = 'e8414a0f3aad33ad8e7ca784b4511198' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = 'd41683f35b5e444a9381f68d296b0f0a'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$§17 Abs. 14 VgV, §8.10.3.1$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF (client_organization_type != 'privat_ohne_foerderung' OR vergaberecht_freiwillig_angewendet == true) AND procurement_procedure == 'vgv_f' THEN (negotiation_rounds >= 1)$m$,
       description = $m$Gilt beim VgV-F-Verfahren (procurement_procedure auf M820-10), wenn der Auftraggeber an das Vergaberecht gebunden ist (kein privater Auftraggeber ohne Fördermittel, oder vergaberecht_freiwillig_angewendet = ja; beides auf M820-01). Bei Suchverfahren, Direktvergabe oder Planungswettbewerb prüft sie nicht. Zum Bestehen muss negotiation_rounds auf diesem Blatt dann mindestens 1 sein. §8.10.3.1 (S. 39–40): Das Verhandlungsverfahren sieht die Abforderung „endgültiger Angebote nach der Durchführung von Verhandlungen nunmehr zwingend vor“ (§ 17 Abs. 14 VgV).
[EN] Applies in a VgV-F procedure (procurement_procedure on M820-10) when the client is bound by procurement law (not a private client without public funding, or vergaberecht_freiwillig_angewendet = yes; both on M820-01). It does not check in a search procedure, direct award or design competition. To pass, negotiation_rounds on this sheet must then be at least 1. §8.10.3.1 (pp. 39–40): the negotiated procedure now mandatorily requires final offers only after negotiations (§ 17 Abs. 14 VgV).$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-20' AND cr.code = 'REQ-20'
   AND md5(cr.condition) = 'e8414a0f3aad33ad8e7ca784b4511198' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = 'd41683f35b5e444a9381f68d296b0f0a'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$§17 Abs. 14 VgV, §8.10.3.1$m$;
-- DWA-M-820-1 M820-21 REQ-21: condition, description
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-21' AND cr.code = 'REQ-21'
   AND md5(cr.condition) = '2abd8dde1cc68902f46805656819a465' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = '2510f43341c4295dbddaf965281ffdbc'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$8.10.3.5$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF (client_organization_type != 'privat_ohne_foerderung' OR vergaberecht_freiwillig_angewendet == true) AND procurement_procedure == 'vgv_f' THEN (vertragsentwurf_in_unterlagen == true)$m$,
       description = $m$Gilt beim VgV-F-Verfahren (procurement_procedure auf M820-10), wenn der Auftraggeber an das Vergaberecht gebunden ist (kein privater Auftraggeber ohne Fördermittel, oder vergaberecht_freiwillig_angewendet = ja; beides auf M820-01). Bei Suchverfahren, Direktvergabe oder Planungswettbewerb prüft sie nicht. Zum Bestehen muss der Vertragsentwurf dann Teil der Vergabeunterlagen sein (vertragsentwurf_in_unterlagen, dieses Blatt). §8.10.3.5 (S. 41): „Ein Vertragsentwurf muss bereits Teil der Vergabeunterlagen und der Verhandlung sein“; er ist vor der Wertung der endgültigen Angebote abschließend zu klären.
[EN] Applies in a VgV-F procedure (procurement_procedure on M820-10) when the client is bound by procurement law (not a private client without public funding, or vergaberecht_freiwillig_angewendet = yes; both on M820-01). It does not check in a search procedure, direct award or design competition. To pass, the contract draft must then be part of the procurement documents (vertragsentwurf_in_unterlagen, this sheet). §8.10.3.5 (p. 41): "a contract draft must already be part of the procurement documents and of the negotiation"; it is to be settled before the final offers are scored.$m$
  FROM worksheet_templates w, standards s
