   AND md5(cr.condition) = '2abd8dde1cc68902f46805656819a465' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = '2510f43341c4295dbddaf965281ffdbc'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$8.10.3.5$m$;
-- DWA-M-820-1 M820-24 REQ-23: condition, description
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND cr.code = 'REQ-23'
   AND md5(cr.condition) = '477dc985356d934ed67b472a9a80dd31' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = '6f1a34b99a8e33a3eaf0ea36d62e240f'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$§8 VgV, §8.3, Anh. F$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET condition = $m$IF (client_organization_type != 'privat_ohne_foerderung' OR vergaberecht_freiwillig_angewendet == true) AND procurement_procedure == 'vgv_f' THEN (vergabevermerk_complete == true)$m$,
       description = $m$Gilt beim VgV-F-Verfahren (procurement_procedure auf M820-10), wenn der Auftraggeber an das Vergaberecht gebunden ist (kein privater Auftraggeber ohne Fördermittel, oder vergaberecht_freiwillig_angewendet = ja; beides auf M820-01). Bei Suchverfahren, Direktvergabe oder Planungswettbewerb prüft sie nicht. Zum Bestehen muss vergabevermerk_complete dann bestätigt sein. §8.3 (S. 32): „Als Abschluss des Vergabeverfahrens ist ein Vergabevermerk anzufertigen (§ 8 VgV).“ Bei Direktvergabe oder Suchverfahren ist der Auftraggeber „zwar nicht dazu verpflichtet“, sollte ihn aber fertigen. Anhang F schlägt eine Gliederung vor.
[EN] Applies in a VgV-F procedure (procurement_procedure on M820-10) when the client is bound by procurement law (not a private client without public funding, or vergaberecht_freiwillig_angewendet = yes; both on M820-01). It does not check in a search procedure, direct award or design competition. To pass, vergabevermerk_complete must then be confirmed. §8.3 (p. 32): "a procurement memo is to be prepared to close the procedure (§ 8 VgV)." For a direct award or search procedure the client is not obliged, but should prepare one. Anhang F proposes a structure.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-24' AND cr.code = 'REQ-23'
   AND md5(cr.condition) = '477dc985356d934ed67b472a9a80dd31' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = '6f1a34b99a8e33a3eaf0ea36d62e240f'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$§8 VgV, §8.3, Anh. F$m$;
-- DWA-M-820-1 M820-25 REQ-25: severity, description (block → warn; tool; „— (Werkzeug-Prüfung)“)
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-25' AND cr.code = 'REQ-25'
   AND md5(cr.condition) = '98c539d9caf2590e480533498bb9c7c1' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = 'b317a87efbb0334e401a06dfa55a961b'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$§4.1, Bild 2-3$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET severity = $m$warn$m$,
       description = $m$Werkzeug-Prüfung (das Konformitätsurteil ist kein gedruckter Begriff des Merkblatts) – warnt nur, sperrt die Freigabe nicht. Erfüllt, wenn das Urteil „konform“ oder „konform mit Auflagen“ lautet. Maßstab sind die Qualitätsziele für Konzept (Bild 2) und Projekte (Bild 3), die im Vergabeverlauf zu erreichen waren.
[EN] Tool check (the compliance verdict is not a printed term of the Merkblatt) – warns only, never blocks approval. Met when the verdict reads "compliant" or "compliant with conditions". The yardstick is the quality targets for the concept (Bild 2) and the project (Bild 3) that had to be met along the way.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-1' AND w.code = 'M820-25' AND cr.code = 'REQ-25'
   AND md5(cr.condition) = '98c539d9caf2590e480533498bb9c7c1' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = 'b317a87efbb0334e401a06dfa55a961b'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$§4.1, Bild 2-3$m$;
