-- DWA-M-820-3 M8203-01 REQ-01: severity, description (block → warn; tool; „— (Werkzeug-Prüfung)“)
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND cr.code = 'REQ-01'
   AND md5(cr.condition) = 'dcd6e4dd93debe8cd87cc3b29dd72b84' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = '56265dca9a12bd099dc521db4940ef61'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$1 Anwendungsbereich$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET severity = $m$warn$m$,
       description = $m$Werkzeug-Prüfung (Geltungsbereich, keine gedruckte Pflicht) – warnt nur, sperrt die Freigabe nicht. Erfüllt, wenn mindestens einer der vier Bereiche (Wasserwirtschaft, Wasserbau, Abwasser, Abfall) bejaht ist und Auftraggeber und Auftragnehmer eingetragen sind (alle auf diesem Blatt). § 1 (gedruckt S. 7): Das Merkblatt „richtet sich an Auftraggeber und Auftragnehmer“ für Anlagen in den Bereichen Wasserwirtschaft, Wasserbau, Abwasser und Abfall.
[EN] Tool check (scope, not a printed duty) – warns only, never blocks approval. Met when at least one of the four fields (water management, hydraulic engineering, wastewater, waste) is Yes and both client and contractor are entered (all on this sheet). § 1 (printed p. 7): the Merkblatt addresses clients and contractors for facilities in water management, hydraulic engineering, wastewater and waste.$m$
  FROM worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-01' AND cr.code = 'REQ-01'
   AND md5(cr.condition) = 'dcd6e4dd93debe8cd87cc3b29dd72b84' AND cr.severity = 'block' AND md5(coalesce(cr.description, '')) = '56265dca9a12bd099dc521db4940ef61'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$1 Anwendungsbereich$m$;
-- DWA-M-820-3 M8203-02 REQ-02: description
INSERT INTO compliance_requirements_archive_m820_gc SELECT cr.* FROM compliance_requirements cr, worksheet_templates w, standards s
 WHERE cr.worksheet_template_id = w.id AND w.standard_id = s.id AND s.code = 'DWA-M-820-3' AND w.code = 'M8203-02' AND cr.code = 'REQ-02'
