   AND md5(cr.condition) = '95eacfbc561e3d4aef0c90e1b7d42e5a' AND cr.severity = 'warn' AND md5(coalesce(cr.description, '')) = '7625d91f5bb93852b6373d116f9dfe23'
   AND cr.clause_reference IS NOT DISTINCT FROM $m$Anhang A.1$m$
   AND NOT EXISTS (SELECT 1 FROM compliance_requirements_archive_m820_gc a WHERE a.id = cr.id);
UPDATE compliance_requirements cr
   SET description = $m$Prüft, ob Ihre manuellen Zählfelder Y+P+N+NA aller 15 gedruckten Kriterien aus Anhang A.1 (QE 5.2: Bedarfsplanung Konzept) die Gesamtzahl 15 ergeben. Das Merkblatt sieht die Prüfung der Phasenziele mit diesen Qualitätselementen als Möglichkeit vor (Vorwort, S. 3: „kann … überprüft werden“); die Prüfung ist daher eine Warnung, kein Blocker. Gilt für jedes Projekt mit diesem Arbeitsblatt; maßgeblich sind die vier Zählfelder Y/P/N/NA und die Gesamtzahl. Zum Bestehen: bewerten Sie alle 15 Kriterien (z. B. im Register) und tragen Sie die Anzahlen Y, P, N und NA in die Zählfelder ein, sodass ihre Summe der Gesamtzahl entspricht. Werkzeug-Prüfung (keine gedruckte Vorgabe des Merkblatts) – warnt nur, sperrt die Freigabe nicht.
[EN] Checks whether your manual count fields Y+P+N+NA across all 15 printed Anhang A.1 criteria (QE 5.2: Bedarfsplanung Konzept) add up to 15. The guideline offers these quality elements as a means to check the Phasenziele (Vorwort, p. 3: „kann … überprüft werden“); the check is therefore a warning, not a blocker. Applies to every project using this sheet; driven by the four count fields Y/P/N/NA and the total. To pass: rate all 15 criteria (e.g. in the register) and enter the Y, P, N and NA counts in the count fields so that their sum equals the total. Tool check (not a printed requirement of the Merkblatt) – warns only, never blocks approval.$m$
