-- ── 4. regulation table rows (1-3 ANHB23 139.000 € tier; 3-1 catalogue row "E" per QE table) ──
WITH ins AS (
  INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
  SELECT t.id, $m$vergleichbare_institution$m$, $m${"organisation":"vergleichbare_institution"}$m$::jsonb, NULL, $m$Vergleichbare Institution — der obersten oder oberen Bundesbehörden oder vergleichbarer Institutionen$m$, 8, $m${"gueltig_ab":"01.01.2020","verordnung":"Verordnung (EU) 2019/1828 vom 30.10.2019","gruppe_gedruckt":"der obersten oder oberen Bundesbehörden oder vergleichbarer Institutionen","schwellenwert_eur":139000}$m$::jsonb, $m$der obersten oder oberen Bundesbehörden oder vergleichbarer Institutionen 139.000 €,$m$
    FROM regulation_tables t WHERE t.standard_code = 'DWA-M-820-1' AND t.edition = '2020' AND t.table_code = 'ANHB23'
     AND NOT EXISTS (SELECT 1 FROM regulation_table_rows x WHERE x.table_id = t.id AND x.row_key = $m$vergleichbare_institution$m$)
