-- ── 5. new optional goal fields (3-5) — copied from the sibling field: section, visibility, validation ──
WITH ins AS (
  INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, validation_rules, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, consumer_worksheets, order_index, active)
  SELECT w.id, sib.section_id, $m$bim_roles_defined$m$, $m$Rollen AG/AN und BIM-Management/-Koordination geklärt$m$, $m$Client/contractor roles and BIM management/coordination clarified$m$, 'boolean', NULL, false, sib.validation_rules, $m$§7.2.2$m$,
         $m$Ja/Nein: sind Rollen und Abgrenzungen zwischen AG und AN definiert und ist geklärt, wer BIM-Management und BIM-Koordination übernimmt? § 7.2.2 Ziele (gedruckt S. 19): „Die Rollen und die Abgrenzungen zwischen AG und AN sind definiert. Es ist geklärt, wer das BIM-Management und die BIM-Koordination übernimmt (Planer oder AG).“ Gedruckt als Zielbild (ohne Modalverb); optional, keine Prüfung liest das Feld. Nur sichtbar bei BIM-Anwendung.
[EN] Yes/No: are the roles and boundaries between client and contractor defined, and is it clear who takes on BIM management and BIM coordination? § 7.2.2 goals (printed p. 19): "The roles and boundaries between client and contractor are defined. It is clarified who takes on BIM management and BIM coordination (planner or client)." Printed as a target state (no modal verb); optional, no check reads this field. Only shown when BIM is applied.$m$,
         'imported_unverified', $m$Die Rollen und die Abgrenzungen zwischen AG und AN sind definiert. Es ist geklärt, wer das BIM-Management und die BIM-Koordination übernimmt (Planer oder AG).$m$, $m$DWA-M 820-3 § 7.2.2 Ziele (PDF S. 21)$m$, NULL, NULL, NULL, sib.visible_when, NULL, NULL,
         (SELECT COALESCE(MAX(f3.order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
    FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id JOIN fields sib ON sib.worksheet_template_id = w.id AND sib.symbol = 'cde_platform_defined' AND sib.active
   WHERE s.code = 'DWA-M-820-3' AND w.code = 'M8203-19'
     AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = $m$bim_roles_defined$m$)
  RETURNING *
)
INSERT INTO m820_gc_added (tbl, id, md5) SELECT 'fields', ins.id, md5(row_to_json(ins)::text) FROM ins ON CONFLICT DO NOTHING;
WITH ins AS (
  INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit, is_required, validation_rules, clause_reference, description, verification_status, verification_quote, source_anchor, widget, ui_config, lookup, visible_when, enum_values, consumer_worksheets, order_index, active)
  SELECT w.id, sib.section_id, $m$bim_planning_data_digital$m$, $m$Planungsrelevante Daten (inkl. Bestandsdaten) digital und abgestimmt verfügbar$m$, $m$Planning-relevant data (incl. as-built data) available in agreed digital form$m$, 'boolean', NULL, false, sib.validation_rules, $m$§7.2.2$m$,
         $m$Ja/Nein: liegen alle planungsrelevanten Daten und Informationen in geeigneter, abgestimmter digitaler Form vor, vom Planer bestätigt? § 7.2.2 Ziele (gedruckt S. 19): „Alle für die Planung relevanten Daten (einschließlich Bestandsdaten) und Informationen liegen in geeigneter und abgestimmter digitaler Form vor. Die Anforderungen des Planers sind erfüllt und von ihm bestätigt.“ Gedruckt als Zielbild (ohne Modalverb); optional, keine Prüfung liest das Feld. Nur sichtbar bei BIM-Anwendung.
[EN] Yes/No: are all planning-relevant data and information available in suitable, agreed digital form, confirmed by the planner? § 7.2.2 goals (printed p. 19): "All data relevant for planning (including as-built data) and information are available in suitable and agreed digital form. The planner's requirements are met and confirmed by the planner." Printed as a target state (no modal verb); optional, no check reads this field. Only shown when BIM is applied.$m$,
         'imported_unverified', $m$Alle für die Planung relevanten Daten (einschließlich Bestandsdaten) und Informationen liegen in geeigneter und abgestimmter digitaler Form vor. Die Anforderungen des Planers sind erfüllt und von ihm bestätigt.$m$, $m$DWA-M 820-3 § 7.2.2 Ziele (PDF S. 21)$m$, NULL, NULL, NULL, sib.visible_when, NULL, NULL,
         (SELECT COALESCE(MAX(f3.order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
    FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id JOIN fields sib ON sib.worksheet_template_id = w.id AND sib.symbol = 'cde_platform_defined' AND sib.active
   WHERE s.code = 'DWA-M-820-3' AND w.code = 'M8203-19'
     AND NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = $m$bim_planning_data_digital$m$)
  RETURNING *
)
