  SELECT w.id, sib.section_id, $m$bim_model_communication$m$, $m$Planungskommunikation weitgehend im BIM-Modell$m$, $m$Planning communication largely in the BIM model$m$, 'boolean', NULL, false, sib.validation_rules, $m$§7.5.2$m$,
         $m$Ja/Nein: findet die Kommunikation zu den Planungsschritten weitgehend im BIM-Modell statt? § 7.5.2 Ziele (gedruckt S. 21): „Kommunikation im Rahmen der Planungsschritte findet weitgehend im BIM-Modell statt. (Planungsfragen, Planungsänderungen, Kollisionen).“ Gedruckt als Zielbild (ohne Modalverb); optional, keine Prüfung liest das Feld. Nur bei BIM-Anwendung (M8203-19) sichtbar.
