         'imported_unverified', $m$Kommunikation im Rahmen der Planungsschritte findet weitgehend im BIM-Modell statt. (Planungsfragen, Planungsänderungen, Kollisionen).$m$, $m$DWA-M 820-3 § 7.5.2 Ziele (PDF S. 23)$m$, NULL, NULL, NULL, sib.visible_when, NULL, NULL,
